INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22301, 'តើតារាងទិន្នន័យណាមួយជាស្ថិតិមានពីរអថេរ?', NULL, '["ពិន្ទុសិស្សនិងចំនួនសិស្សក្នុងថ្នាក់មួយ", "កម្ពស់សិស្សនិងចំនួនសិស្សដែលមានកម្ពស់នោះ", "ប្រាក់ចំណេញរបស់ក្រុមហ៊ុនតាមឆ្នាំនីមួយៗ", "ចំនួនកូនក្នុងគ្រួសារនិងចំនួនគ្រួសារ"]', 2, NULL, 1, 'mcq', 'ស្ថិតិមានពីរអថេរសិក្សាពីទំនាក់ទំនងរវាងអថេរពីរផ្សេងគ្នា (ដូចជាឆ្នាំ និងប្រាក់ចំណេញ) ។', 'សញ្ញាណស្ថិតិមានពីរអថេរ', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22302, 'បើចំណុចទិន្នន័យគឺ \((1, 48), (2, 48.4), (3, 49.5)\) តើចំណុចទី ២ មានកូអរដោនេអ្វីក្នុងតម្រុយកែង?', NULL, '["\\((1, 48)\\)", "\\((3, 49.5)\\)", "\\((48.4, 2)\\)", "\\((2, 48.4)\\)"]', 3, NULL, 1, 'mcq', 'ចំណុចទី ២ មានអាប់ស៊ីស \(x_2 = 2\) និងអរដោនេ \(y_2 = 48.4\) គឺ \((2, 48.4)\) ។', 'បំណកស្រាយស្ថិតិមានពីរអថេរតាមក្រាប', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22303, 'គណនាមធ្យម \(\overline{x}\) នៃសំណុំតម្លៃ \(x_i: 2, 4, 6, 8\) ៖', NULL, '["\\(5\\)", "\\(6\\)", "\\(20\\)", "\\(4\\)"]', 0, NULL, 1, 'mcq', '\(\overline{x} = \frac{2 + 4 + 6 + 8}{4} = \frac{20}{4} = 5\) ។', 'ចំណុចមធ្យម', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22304, 'រកមេគុណប្រាប់ទិសនៃបន្ទាត់ដែលកាត់តាមចំណុចមធ្យម \(M_1(2, 5)\) និង \(M_2(6, 13)\) ៖', NULL, '["\\(0.5\\)", "\\(4\\)", "\\(3\\)", "\\(2\\)"]', 3, NULL, 1, 'mcq', '\(a = \frac{13 - 5}{6 - 2} = \frac{8}{4} = 2\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22305, 'ក្នុងស្ថិតិមានពីរអថេរ សំណុំចំណុច \((x_i, y_i)\) ទាំងអស់ដែលដៅក្នុងតម្រុយកែងហៅថាអ្វី?', NULL, '["បន្ទាត់តម្រែតម្រង់", "ហ៊ីស្តូក្រាម", "ពពកចំណុចទិន្នន័យ (Scatter Plot)", "ដ្យាក្រាមផ្លិត"]', 2, NULL, 1, 'mcq', 'សំណុំចំណុចទិន្នន័យទាំងអស់ក្នុងតម្រុយកែងហៅថា ពពកចំណុចទិន្នន័យ ។', 'សញ្ញាណស្ថិតិមានពីរអថេរ', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22306, 'គណនាមធ្យម \(\overline{y}\) នៃសំណុំតម្លៃ \(y_i: 10, 14, 18, 22\) ៖', NULL, '["\\(15\\)", "\\(16\\)", "\\(14\\)", "\\(18\\)"]', 1, NULL, 1, 'mcq', '\(\overline{y} = \frac{10 + 14 + 18 + 22}{4} = \frac{64}{4} = 16\) ។', 'ចំណុចមធ្យម', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22307, 'បន្ទាត់តម្រែតម្រង់មានសមីការ \(y = 3x + 4\) ។ ប៉ាន់ស្មានតម្លៃ \(y\) នៅពេល \(x = 10\) ៖', NULL, '["\\(38\\)", "\\(34\\)", "\\(43\\)", "\\(30\\)"]', 1, NULL, 1, 'mcq', 'ជំនួស \(x = 10\) បាន \(y = 3(10) + 4 = 34\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22308, 'គេឱ្យចំណុច \((1, 48), (2, 48.4), (3, 49.5), (4, 48.9), (5, 49.3), (6, 48.7)\) ។ រកចំណុចមធ្យម \(M(\overline{x}, \overline{y})\) ៖', NULL, '["\\(M(3.5, 48.8)\\)", "\\(M(4, 48.5)\\)", "\\(M(3, 48.8)\\)", "\\(M(3.5, 49)\\)"]', 0, NULL, 1, 'mcq', '\(\overline{x} = \frac{21}{6} = 3.5\) និង \(\overline{y} = \frac{292.8}{6} = 48.8\) ។', 'ចំណុចមធ្យម', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22309, 'ដើម្បីរកបន្ទាត់តម្រែតម្រង់តាមវិធីចំណុចមធ្យមពីរ បើមានទិន្នន័យ \(8\) ចំណុច តើគេចែកជាពីរក្រុមយ៉ាងដូចម្តេច?', NULL, '["តម្រៀបតាមអាប់ស៊ីសកើន រួចចែកជា \\(4\\) ចំណុច និង \\(4\\) ចំណុច", "ចែកជា \\(2\\) ចំណុច និង \\(6\\) ចំណុច", "ចែកជា \\(3\\) ចំណុច និង \\(5\\) ចំណុចដោយមិនបាច់តម្រៀប", "យកតែចំណុចដំបូង និងចំណុចចុងក្រោយ"]', 0, NULL, 1, 'mcq', 'ដោយ \(n = 8\) ជាចំនួនគូ គេតម្រៀបតាមអាប់ស៊ីសកើន រួចចែកជាពីរក្រុមស្មើគ្នា (ក្រុមនីមួយៗមាន \(4\) ចំណុច) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22310, 'រកចំណុចមធ្យម \(M\) នៃទិន្នន័យ \((1, 3), (3, 7), (5, 11), (7, 15)\) ៖', NULL, '["\\(M(3.5, 9)\\)", "\\(M(4, 9)\\)", "\\(M(5, 10)\\)", "\\(M(4, 8)\\)"]', 1, NULL, 1, 'mcq', '\(\overline{x} = \frac{1+3+5+7}{4} = 4\) និង \(\overline{y} = \frac{3+7+11+15}{4} = 9\) ។', 'ចំណុចមធ្យម', 'easy', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22311, 'គេឱ្យតារាងទិន្នន័យ \((2, 7), (4, 10), (6, 13), (8, 15), (9, 20), (10, 28)\) ។ រកចំណុចមធ្យម \(M\) ៖', NULL, '["\\(M(6, 15)\\)", "\\(M(7, 15.5)\\)", "\\(M(6.5, 16)\\)", "\\(M(6.5, 15.5)\\)"]', 3, NULL, 2, 'mcq', '\(\overline{x} = \frac{39}{6} = 6.5\) និង \(\overline{y} = \frac{93}{6} = 15.5\) ។', 'ចំណុចមធ្យម', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22312, 'គេឱ្យចំណុច \((1, 5), (2, 7), (3, 11), (4, 13)\) ។ រកចំណុចមធ្យម \(M_1\) និង \(M_2\) នៃក្រុមទាំងពីរ ៖', NULL, '["\\(M_1(1.5, 7),\\ M_2(3.5, 11)\\)", "\\(M_1(2, 6),\\ M_2(3, 12)\\)", "\\(M_1(1.5, 6),\\ M_2(3.5, 13)\\)", "\\(M_1(1.5, 6),\\ M_2(3.5, 12)\\)"]', 3, NULL, 2, 'mcq', 'ក្រុមទី ១៖ \((1,5),(2,7) \implies M_1(1.5, 6)\) ។ ក្រុមទី ២៖ \((3,11),(4,13) \implies M_2(3.5, 12)\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22313, 'តើលក្ខណៈណាមួយត្រឹមត្រូវចំពោះការជ្រើសរើសមាត្រដ្ឋានលើអ័ក្សអាប់ស៊ីស និងអ័ក្សអរដោនេក្នុងក្រាបពពកចំណុច?', NULL, '["អ័ក្សអរដោនេមិនអាចប្តូរចំណុចចាប់ផ្ដើមបានទេ", "គល់អ័ក្សត្រូវតែចាប់ផ្ដើមពី \\((0, 0)\\) ជានិច្ច", "ឯកតាលើអ័ក្សទាំងពីរអាចស្មើគ្នា ឬមិនស្មើគ្នា និងអាចកាត់គល់អ័ក្សឱ្យសមស្របតាមទិន្នន័យ", "ឯកតាលើអ័ក្សទាំងពីរត្រូវតែស្មើគ្នាជានិច្ច"]', 2, NULL, 2, 'mcq', 'ក្នុងតម្រុយកែង ឯកតាលើអ័ក្សទាំងពីរអាចស្មើគ្នា ឬមិនស្មើគ្នា ហើយអាចជ្រើសគល់អ័ក្សឱ្យសមស្របនឹងតម្លៃទិន្នន័យ ។', 'បំណកស្រាយស្ថិតិមានពីរអថេរតាមក្រាប', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22314, 'រកសមីការបន្ទាត់ដែលកាត់តាមចំណុចមធ្យម \(M(6.5, 15.5)\) និងចំណុច \((6, 13)\) ៖', NULL, '["\\(y = 5x - 17\\)", "\\(y = 2.5x - 2\\)", "\\(y = 5x + 17\\)", "\\(y = 4x - 11\\)"]', 0, NULL, 2, 'mcq', '\(a = \frac{13 - 15.5}{6 - 6.5} = 5\) ។ ប្រើ \((6, 13)\) បាន \(y - 13 = 5(x - 6) \implies y = 5x - 17\) ។', 'ចំណុចមធ្យម', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22315, 'រកសមីការបន្ទាត់តម្រែតម្រង់ដែលកាត់តាម \(M_1(1.5, 6)\) និង \(M_2(3.5, 12)\) ៖', NULL, '["\\(y = 3x + 1.5\\)", "\\(y = 2x + 3\\)", "\\(y = 4x\\)", "\\(y = 3x - 1.5\\)"]', 0, NULL, 2, 'mcq', '\(a = \frac{12 - 6}{3.5 - 1.5} = 3\) ។ \(b = 6 - 3(1.5) = 1.5\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22316, 'ទិន្នន័យប្រាក់ចំណូលថ្ងៃចន្ទនិងថ្ងៃសៅរ៍គឺ \((43, 72), (65, 83), (56, 79), (63, 84), (56, 80), (56, 76), (56, 74), (51, 79)\) ។ រកចំណុចមធ្យម \(M\) ៖', NULL, '["\\(M(55.75, 79)\\)", "\\(M(55.5, 78.25)\\)", "\\(M(56, 78.5)\\)", "\\(M(55.75, 78.375)\\)"]', 3, NULL, 2, 'mcq', '\(\overline{x} = \frac{446}{8} = 55.75\) និង \(\overline{y} = \frac{627}{8} = 78.375\) ។', 'ចំណុចមធ្យម', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22317, 'គេឱ្យទិន្នន័យ \((2, 10), (3.5, 15), (2.5, 20), (4, 18), (4.5, 30), (5, 35), (6, 40), (6.5, 38), (7, 32), (8, 45)\) ។ រកចំណុចមធ្យម \(M_1\) និង \(M_2\) ៖', NULL, '["\\(M_1(3.3, 19),\\ M_2(6.5, 37)\\)", "\\(M_1(3.3, 18.6),\\ M_2(6.5, 38)\\)", "\\(M_1(3.5, 18.6),\\ M_2(6, 38)\\)", "\\(M_1(3.1, 18.6),\\ M_2(6.5, 39)\\)"]', 1, NULL, 2, 'mcq', 'ក្រោយតម្រៀបតាម \(x\) កើន ក្រុមទី ១ មាន \(5\) ចំណុចដំបូងបាន \(M_1(3.3, 18.6)\) និងក្រុមទី ២ បាន \(M_2(6.5, 38)\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22318, 'ទិន្នន័យ \(4\) ចំណុចមាន \(x_i: 6, 8, 10, a\) និងមធ្យម \(\overline{x} = 9\) ។ រកតម្លៃ \(a\) ៖', NULL, '["\\(12\\)", "\\(10\\)", "\\(8\\)", "\\(14\\)"]', 0, NULL, 2, 'mcq', '\(\frac{6 + 8 + 10 + a}{4} = 9 \implies 24 + a = 36 \implies a = 12\) ។', 'ចំណុចមធ្យម', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22319, 'រកសមីការបន្ទាត់តម្រែតម្រង់កាត់តាម \(M_1(3.3, 18.6)\) និង \(M_2(6.5, 38)\) ៖', NULL, '["\\(y = 5.5x + 0.45\\)", "\\(y = \\frac{97}{16}x + \\frac{45}{32}\\)", "\\(y = \\frac{97}{16}x - \\frac{45}{32}\\)", "\\(y = 6x - 1.2\\)"]', 2, NULL, 2, 'mcq', '\(a = \frac{38 - 18.6}{6.5 - 3.3} = \frac{19.4}{3.2} = \frac{97}{16}\) និង \(b = 38 - \frac{97}{16}(6.5) = -\frac{45}{32}\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22320, 'ទិន្នន័យ \(5\) ចំណុចមានមធ្យម \(\overline{y} = 18\) ។ បើបួនចំណុចដំបូងមាន \(y_i: 12, 15, 18, 20\) រក \(y_5\) ៖', NULL, '["\\(22\\)", "\\(24\\)", "\\(25\\)", "\\(20\\)"]', 2, NULL, 2, 'mcq', '\(y_5 = 5(18) - (12 + 15 + 18 + 20) = 90 - 65 = 25\) ។', 'ចំណុចមធ្យម', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22321, 'បើទិន្នន័យមាន \(5\) ចំណុចគឺ \((1, 2), (2, 5), (3, 6), (4, 9), (5, 10)\) ដោយដាក់ \(3\) ចំណុចក្នុងក្រុមទី ១ និង \(2\) ចំណុចក្នុងក្រុមទី ២ តើ \(M_2\) ស្មើនឹងអ្វី?', NULL, '["\\(M_2(4, 9)\\)", "\\(M_2(4.5, 8.5)\\)", "\\(M_2(3.5, 9.5)\\)", "\\(M_2(4.5, 9.5)\\)"]', 3, NULL, 2, 'mcq', 'ក្រុមទី ២ មាន \((4, 9), (5, 10)\) នាំឱ្យ \(M_2\left(\frac{4+5}{2}, \frac{9+10}{2}\right) = M_2(4.5, 9.5)\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22322, 'សម្រាប់ទិន្នន័យ \((2, 7), (4, 10), (6, 11), (8, 13), (9, 17), (12, 19), (14, 23)\) ចែកក្រុមទី ១ មាន \(4\) ចំណុច និងក្រុមទី ២ មាន \(3\) ចំណុច ។ រក \(M_1\) ៖', NULL, '["\\(M_1(6, 11)\\)", "\\(M_1(5, 10.25)\\)", "\\(M_1(5, 10.5)\\)", "\\(M_1(4.5, 10.25)\\)"]', 1, NULL, 2, 'mcq', '\(\overline{x}_1 = \frac{2+4+6+8}{4} = 5\) និង \(\overline{y}_1 = \frac{7+10+11+13}{4} = 10.25\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22323, 'បន្ទាត់តម្រែតម្រង់កាត់តាម \(M_1(1\,972, 12.86)\) និង \(M_2(1\,976.5, 12.475)\) ។ រកមេគុណប្រាប់ទិស \(a\) ជាប្រភាគសម្រួល ៖', NULL, '["\\(-\\frac{11}{150}\\)", "\\(-\\frac{77}{450}\\)", "\\(-\\frac{77}{900}\\)", "\\(\\frac{77}{900}\\)"]', 2, NULL, 2, 'mcq', '\(a = \frac{12.475 - 12.86}{1\,976.5 - 1\,972} = \frac{-0.385}{4.5} = -\frac{77}{900}\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22324, 'បន្ទាត់តម្រែតម្រង់សម្ពាធបរិយាកាសតាមកម្ពស់គឺ \(y = -5x + 70\) (\(x\) គិតជា \(\text{km}\), \(y\) គិតជា \(\text{cm}\) បារត) ។ រកកម្ពស់ពេល \(y = 40\text{ cm}\) ៖', NULL, '["\\(4\\text{ km}\\)", "\\(6\\text{ km}\\)", "\\(8\\text{ km}\\)", "\\(5\\text{ km}\\)"]', 1, NULL, 2, 'mcq', '\(40 = -5x + 70 \implies 5x = 30 \implies x = 6\text{ km}\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22325, 'ដោយប្រើទិន្នន័យ \((1, 48), (2, 48.4), (3, 49.5), (4, 48.9), (5, 49.3), (6, 48.7)\) ចែកជា ២ ក្រុមស្មើគ្នា រកមេគុណប្រាប់ទិសពិតប្រាកដនៃបន្ទាត់តម្រែតម្រង់ ៖', NULL, '["\\(\\frac{1}{9}\\)", "\\(\\frac{2}{9}\\)", "\\(\\frac{1}{6}\\)", "\\(\\frac{1}{3}\\)"]', 0, NULL, 3, 'mcq', '\(G_1\left(2, \frac{145.9}{3}\right)\), \(G_2\left(5, \frac{146.9}{3}\right) \implies a = \frac{1/3}{3} = \frac{1}{9}\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22326, 'បន្ទាត់តម្រែតម្រង់មានមេគុណប្រាប់ទិស \(\frac{1}{9}\) និងកាត់តាម \(G_1\left(2, \frac{1\,459}{30}\right)\) ។ គណនាតម្លៃពិតប្រាកដនៃ \(y\) ពេល \(x = 8\) ៖', NULL, '["\\(49.3\\)", "\\(48.9\\)", "\\(49.5\\)", "\\(49.1\\)"]', 0, NULL, 3, 'mcq', '\(y = \frac{1}{9}(8 - 2) + \frac{1\,459}{30} = \frac{2}{3} + 48.6333\dots = 49.3\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22327, 'ទិន្នន័យកម្ពស់ និងសម្ពាធបរិយាកាសគឺ \((0, 76), (1, 67), (2, 59), (4, 46), (6, 35), (10, 20)\) ។ តាមបន្ទាត់តម្រែតម្រង់ចំណុចមធ្យមពីរ រកកម្ពស់ពិតប្រាកដពេល \(y = 40\) ៖', NULL, '["\\(\\frac{1\\,700}{303}\\text{ km}\\)", "\\(\\frac{1\\,697}{303}\\text{ km}\\)", "\\(\\frac{1\\,600}{303}\\text{ km}\\)", "\\(\\frac{500}{101}\\text{ km}\\)"]', 1, NULL, 3, 'mcq', '\(M_1\left(1, \frac{202}{3}\right),\ M_2\left(\frac{20}{3}, \frac{101}{3}\right)\) ឱ្យ \(y = -\frac{101}{17}x + \frac{3\,737}{51}\) ។ ដោះស្រាយ \(y = 40 \implies x = \frac{1\,697}{303}\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22328, 'ទិន្នន័យចំណាយសាងសង់ \((0, 24), (1, 19), (2, 30), (3, 49), (4, 68), (5, 67)\) ។ រកសមីការបន្ទាត់តម្រែតម្រង់កាត់តាមចំណុចមធ្យមពីរ ៖', NULL, '["\\(y = \\frac{37}{3}x + 10\\)", "\\(y = \\frac{37}{3}x + 12\\)", "\\(y = \\frac{35}{3}x + 12\\)", "\\(y = 12x + 13\\)"]', 1, NULL, 3, 'mcq', '\(M_1\left(1, \frac{73}{3}\right),\ M_2\left(4, \frac{184}{3}\right) \implies a = \frac{111/3}{3} = \frac{37}{3}\), \(b = \frac{73}{3} - \frac{37}{3} = 12\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22329, 'ដោយប្រើបន្ទាត់តម្រែតម្រង់ \(y = \frac{37}{3}x + 12\) (ពីទិន្នន័យ \(x = 0\) តាងខែមេសា ដល់ \(x = 5\) តាងខែកញ្ញា) ប៉ាន់ស្មានចំណាយក្នុងខែតុលា (\(x = 6\)) ៖', NULL, '["\\(88\\) ពាន់ដុល្លារ", "\\(84\\) ពាន់ដុល្លារ", "\\(74\\) ពាន់ដុល្លារ", "\\(86\\) ពាន់ដុល្លារ"]', 3, NULL, 3, 'mcq', '\(y(6) = \frac{37}{3}(6) + 12 = 74 + 12 = 86\) ពាន់ដុល្លារ ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22330, 'បន្ទាត់តម្រែតម្រង់កាត់តាម \(M_1(1\,953, 1.925)\) និង \(M_2(1\,961, 3.5)\) ។ រកតម្លៃពិតប្រាកដនៃមេគុណប្រាប់ទិស \(a\) ៖', NULL, '["\\(\\frac{61}{320}\\)", "\\(\\frac{31}{160}\\)", "\\(\\frac{63}{320}\\)", "\\(\\frac{65}{320}\\)"]', 2, NULL, 3, 'mcq', '\(a = \frac{3.5 - 1.925}{1\,961 - 1\,953} = \frac{1.575}{8} = \frac{63}{320} = 0.196875\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22331, 'បើទិន្នន័យមួយមានចំណុចទាំងអស់ស្ថិតនៅលើបន្ទាត់តែមួយ \(y = 2x + 5\) តើបន្ទាត់តម្រែតម្រង់កាត់តាមចំណុចមធ្យមពីរមានសមីការដូចម្តេច?', NULL, '["កាត់តាមគល់ \\((0, 0)\\)", "មានមេគុណប្រាប់ទិសស្មើ \\(0\\)", "\\(y = 2x + 5\\) ដដែល ព្រោះចំណុចមធ្យមនៃក្រុមទាំងពីរស្ថិតលើបន្ទាត់នោះដែរ", "ខុសពី \\(y = 2x + 5\\) ជានិច្ច"]', 2, NULL, 3, 'mcq', 'ចំណុចមធ្យមនៃសំណុំចំណុចដែលស្ថិតលើបន្ទាត់មួយតែងតែស្ថិតលើបន្ទាត់នោះដែរ ដូច្នេះបន្ទាត់ភ្ជាប់ \(M_1M_2\) គឺជាបន្ទាត់ \(y = 2x + 5\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Evaluate');
