INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22332, 'រោងពុម្ពមួយកត់ត្រាចំនួនសៀវភៅ (ម៉ឺនក្បាល) តាមឆ្នាំទី \(x_i\)៖ \((1, 48), (2, 48.4), (3, 49.5), (4, 48.9), (5, 49.3), (6, 48.7)\) ។ គណនាមធ្យមចំនួនសៀវភៅក្នុងមួយឆ្នាំ ៖', 'g12sc-04e30af578.svg', '["\\(48.9\\) ម៉ឺនក្បាល", "\\(48.7\\) ម៉ឺនក្បាល", "\\(49.0\\) ម៉ឺនក្បាល", "\\(48.8\\) ម៉ឺនក្បាល"]', 3, NULL, 3, 'mcq', '\(\overline{y} = \frac{48 + 48.4 + 49.5 + 48.9 + 49.3 + 48.7}{6} = 48.8\) ម៉ឺនក្បាល ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
