INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22333, 'ប្រាក់ឈ្នួលកម្មករ (ដុល្លារ/ម៉ោង) ពីឆ្នាំ ១៩៥០ ដល់ ១៩៦៤ គឺ \((1\,950, 1.5), (1\,952, 1.8), (1\,954, 1.9), (1\,956, 2.5), (1\,958, 2.8), (1\,960, 3.2), (1\,962, 3.7), (1\,964, 4.3)\) ។ តាមបន្ទាត់ \(y = 0.197x - 382.816\) ប៉ាន់ស្មានប្រាក់ឈ្នួលនៅឆ្នាំ ១៩៦៦ ៖', 'g12sc-8b748eed49.svg', '["\\(3.900\\) ដុល្លារ/ម៉ោង", "\\(4.100\\) ដុល្លារ/ម៉ោង", "\\(4.800\\) ដុល្លារ/ម៉ោង", "\\(4.486\\) ដុល្លារ/ម៉ោង"]', 3, NULL, 3, 'mcq', '\(y = 0.197(1\,966) - 382.816 = 387.302 - 382.816 = 4.486\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
