INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22334, 'សម្ពាធបរិយាកាស (\(\text{cm}\) បារត) តាមកម្ពស់ (\(\text{km}\)) គឺ \((0, 76), (1, 67), (2, 59), (4, 46), (6, 35), (10, 20)\) ។ រកចំណុចមធ្យម \(M_1\) នៃក្រុម \(3\) ចំណុចដំបូង ៖', 'g12sc-597167acec.svg', '["\\(M_1\\left(1, \\frac{202}{3}\\right)\\)", "\\(M_1(1, 66)\\)", "\\(M_1(1.5, 68)\\)", "\\(M_1(1, 67)\\)"]', 0, NULL, 3, 'mcq', '\(\overline{x}_1 = \frac{0 + 1 + 2}{3} = 1\) និង \(\overline{y}_1 = \frac{76 + 67 + 59}{3} = \frac{202}{3}\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
