INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22335, 'ចំណាយសាងសង់ (ពាន់ដុល្លារ) ក្នុង ៦ ខែ (\(x=0\) ដល់ \(5\)) គឺ \((0, 24), (1, 19), (2, 30), (3, 49), (4, 68), (5, 67)\) ។ គណនាមធ្យមចំណាយប្រចាំខែ ៖', 'g12sc-d89f18c831.svg', '["\\(48\\) ពាន់ដុល្លារ", "\\(\\frac{257}{6}\\ (\\approx 42.83)\\) ពាន់ដុល្លារ", "\\(40\\) ពាន់ដុល្លារ", "\\(45\\) ពាន់ដុល្លារ"]', 1, NULL, 3, 'mcq', '\(\overline{y} = \frac{24 + 19 + 30 + 49 + 68 + 67}{6} = \frac{257}{6} \approx 42.83\) ពាន់ដុល្លារ ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
