INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22336, 'ទំនាក់ទំនងតម្លៃ \(p\) (ពាន់រៀល) និងបរិមាណលក់ \(x\) (ពាន់ឯកតា) គឺ \((6.2, 9.6), (6.9, 8), (7.5, 7.3), (8, 5.2), (8.8, 3.8)\) ។ រកចំណុចមធ្យម \(M(\overline{p}, \overline{x})\) ៖', 'g12sc-86e59c3686.svg', '["\\(M(7.4, 6.8)\\)", "\\(M(7.6, 6.5)\\)", "\\(M(7.48, 6.78)\\)", "\\(M(7.5, 7.0)\\)"]', 2, NULL, 3, 'mcq', '\(\overline{p} = \frac{37.4}{5} = 7.48\) និង \(\overline{x} = \frac{33.9}{5} = 6.78\) ។', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 1, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22337, 'គេឱ្យទិន្នន័យ \((2, 7), (4, 10), (6, 13), (8, 15), (9, 20), (10, 28)\) ។ ចូរគណនាចំណុចមធ្យម \(M(\overline{x}, \overline{y})\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'រាប់ចំនួនគូទិន្នន័យសរុប ៖ \(n = 6\) (1 ពិន្ទុ)
គណនាផលបូក \(\sum x_i = 2 + 4 + 6 + 8 + 9 + 10 = 39\) (1 ពិន្ទុ)
ទាញបាន \(\overline{x} = \frac{39}{6} = 6.5\) (1 ពិន្ទុ)
គណនា \(\sum y_i = 7 + 10 + 13 + 15 + 20 + 28 = 93 \implies \overline{y} = \frac{93}{6} = 15.5\) (1 ពិន្ទុ)
ដូច្នេះ ចំណុចមធ្យមគឺ \(M(6.5, 15.5)\) ។ (1 ពិន្ទុ)', 'ចំណុចមធ្យម', 'easy', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22338, 'ចំណុចមធ្យមនៃទិន្នន័យមួយគឺ \(M(6.5, 15.5)\) ។ ចូររកសមីការបន្ទាត់ដែលកាត់តាម \(M\) និងចំណុច \(A(6, 13)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រើរូបមន្តបន្ទាត់កាត់តាមពីរចំណុច ៖ \(\frac{y - 13}{x - 6} = \frac{13 - 15.5}{6 - 6.5}\) (1 ពិន្ទុ)
គណនាមេគុណប្រាប់ទិស ៖ \(a = \frac{-2.5}{-0.5} = 5\) (1 ពិន្ទុ)
សរសេរសមីការបន្ទាត់ ៖ \(y - 13 = 5(x - 6)\) (1 ពិន្ទុ)
ពន្លាត ៖ \(y = 5x - 30 + 13\) (1 ពិន្ទុ)
ដូច្នេះ សមីការបន្ទាត់គឺ \(y = 5x - 17\) ។ (1 ពិន្ទុ)', 'ចំណុចមធ្យម', 'medium', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22339, 'គេឱ្យទិន្នន័យ \((1, 5), (2, 8), (3, 11), (4, 14)\) ។ ចូររកសមីការបន្ទាត់តម្រែតម្រង់កាត់តាមចំណុចមធ្យមពីរ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ចែកជា ២ ក្រុម ៖ ក្រុមទី ១ គឺ \((1, 5), (2, 8)\) និងក្រុមទី ២ គឺ \((3, 11), (4, 14)\) (1 ពិន្ទុ)
រក \(M_1\left(\frac{1+2}{2}, \frac{5+8}{2}\right) = (1.5, 6.5)\) (1 ពិន្ទុ)
រក \(M_2\left(\frac{3+4}{2}, \frac{11+14}{2}\right) = (3.5, 12.5)\) (1 ពិន្ទុ)
គណនាមេគុណប្រាប់ទិស ៖ \(a = \frac{12.5 - 6.5}{3.5 - 1.5} = \frac{6}{2} = 3\) (1 ពិន្ទុ)
ទាញបាន \(y - 6.5 = 3(x - 1.5) \implies y = 3x + 2\) ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22340, 'គេមានចំណុចមធ្យម \(M(55.75, 78.375)\) និងចំណុចទិន្នន័យ \(A(63, 84)\) ។ ចូររកមេគុណប្រាប់ទិស \(a\) ជាប្រភាគសម្រួលនៃបន្ទាត់ \(MA\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រើរូបមន្តមេគុណប្រាប់ទិស ៖ \(a = \frac{y_A - \overline{y}}{x_A - \overline{x}}\) (1 ពិន្ទុ)
ជំនួសតម្លៃ ៖ \(a = \frac{84 - 78.375}{63 - 55.75}\) (1 ពិន្ទុ)
គណនាភាគយកនិងភាគបែង ៖ \(a = \frac{5.625}{7.25}\) (1 ពិន្ទុ)
បំប្លែងជាប្រភាគ ៖ \(\frac{45/8}{29/4} = \frac{45}{8} \cdot \frac{4}{29}\) (1 ពិន្ទុ)
ដូច្នេះ \(a = \frac{45}{58} \approx 0.776\) (ចម្លើយ៖ 45/58) ។ (1 ពិន្ទុ)', 'ចំណុចមធ្យម', 'medium', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22341, 'គេឱ្យទិន្នន័យ \((2, 5), (4, 9), (6, 12), (8, 16), (10, 20), (12, 25)\) ។ ចូររកចំណុចមធ្យម \(M_1, M_2\) និងមេគុណប្រាប់ទិសនៃបន្ទាត់តម្រែតម្រង់ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ចែកជា ២ ក្រុមស្មើគ្នា (៣ ចំណុចក្នុងមួយក្រុម) (1 ពិន្ទុ)
ក្រុមទី ១ ៖ \(\overline{x}_1 = \frac{2+4+6}{3} = 4,\ \overline{y}_1 = \frac{5+9+12}{3} = \frac{26}{3}\) (1 ពិន្ទុ)
ក្រុមទី ២ ៖ \(\overline{x}_2 = \frac{8+10+12}{3} = 10,\ \overline{y}_2 = \frac{16+20+25}{3} = \frac{61}{3}\) (1 ពិន្ទុ)
គណនាមេគុណប្រាប់ទិស ៖ \(a = \frac{\frac{61}{3} - \frac{26}{3}}{10 - 4} = \frac{35/3}{6}\) (1 ពិន្ទុ)
ដូច្នេះ \(a = \frac{35}{18}\) (ចម្លើយ៖ 35/18) ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22342, 'គេឱ្យទិន្នន័យ \((2, 10), (3.5, 15), (2.5, 20), (4, 18), (4.5, 30), (5, 35), (6, 40), (6.5, 38), (7, 32), (8, 45)\) ។ រកសមីការបន្ទាត់តម្រែតម្រង់កាត់តាមចំណុចមធ្យមពីរ ។', NULL, '[]', 0, NULL, 5, 'writing', 'តម្រៀបតាម \(x_i\) កើន ៖ ក្រុមទី ១ គឺ \((2,10), (2.5,20), (3.5,15), (4,18), (4.5,30)\) (1 ពិន្ទុ)
ក្រុមទី ២ គឺ \((5,35), (6,40), (6.5,38), (7,32), (8,45)\) (1 ពិន្ទុ)
រកចំណុចមធ្យម ៖ \(M_1(3.3, 18.6)\) និង \(M_2(6.5, 38)\) (1 ពិន្ទុ)
គណនាមេគុណប្រាប់ទិស ៖ \(a = \frac{38 - 18.6}{6.5 - 3.3} = \frac{19.4}{3.2} = \frac{97}{16}\) (1 ពិន្ទុ)
ទាញបាន \(y = \frac{97}{16}x - \frac{45}{32} \approx 6.0625x - 1.406\) ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22343, 'វត្ថុធាតុដើម (ពាន់តោន) ពីឆ្នាំ ១៩៧០ ដល់ ១៩៧៨ គឺ \((1\,970, 12.4), (1\,971, 13.6), (1\,972, 12.7), (1\,973, 13.3), (1\,974, 12.3), (1\,975, 13), (1\,976, 12), (1\,977, 12.4), (1\,978, 12.5)\) ។ រកសមីការបន្ទាត់តម្រែតម្រង់ដោយចែកក្រុមទី ១ មាន ៥ ចំណុច និងក្រុមទី ២ មាន ៤ ចំណុច ។', NULL, '[]', 0, NULL, 5, 'writing', 'រក \(M_1\) នៃ ៥ ឆ្នាំដំបូង (១៩៧០–១៩៧៤) ៖ \(M_1(1\,972, 12.86)\) (1 ពិន្ទុ)
រក \(M_2\) នៃ ៤ ឆ្នាំចុងក្រោយ (១៩៧៥–១៩៧៨) ៖ \(M_2(1\,976.5, 12.475)\) (1 ពិន្ទុ)
គណនាមេគុណប្រាប់ទិស ៖ \(a = \frac{12.475 - 12.86}{1\,976.5 - 1\,972} = -\frac{77}{900}\) (1 ពិន្ទុ)
រកអរដោនេដើម ៖ \(b = 12.86 - \left(-\frac{77}{900}\right)(1\,972) = \frac{81\,709}{450}\) (1 ពិន្ទុ)
ដូច្នេះ សមីការបន្ទាត់គឺ \(y = -\frac{77}{900}x + \frac{81\,709}{450} \approx -0.0856x + 181.576\) ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22344, 'គេឱ្យទិន្នន័យ \((2, 7), (4, 10), (6, 11), (8, 13), (9, 17), (12, 19), (14, 23)\) ដោយចែកក្រុមទី ១ មាន ៤ ចំណុច និងក្រុមទី ២ មាន ៣ ចំណុច ។ រកសមីការបន្ទាត់តម្រែតម្រង់ជាទម្រង់ប្រភាគពិតប្រាកដ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក្រុមទី ១ ៖ \(M_1\left(\frac{2+4+6+8}{4}, \frac{7+10+11+13}{4}\right) = (5, 10.25)\) (1 ពិន្ទុ)
ក្រុមទី ២ ៖ \(M_2\left(\frac{9+12+14}{3}, \frac{17+19+23}{3}\right) = \left(\frac{35}{3}, \frac{59}{3}\right)\) (1 ពិន្ទុ)
គណនាមេគុណប្រាប់ទិស ៖ \(a = \frac{\frac{59}{3} - \frac{41}{4}}{\frac{35}{3} - 5} = \frac{113/12}{20/3} = \frac{113}{80}\) (1 ពិន្ទុ)
គណនា \(b = \frac{41}{4} - \frac{113}{80}(5) = \frac{820 - 565}{80} = \frac{51}{16}\) (1 ពិន្ទុ)
ដូច្នេះ \(y = \frac{113}{80}x + \frac{51}{16}\) (ប្រហែល \(y = 1.4125x + 3.1875\)) ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22345, 'ប្រើទិន្នន័យបោះពុម្ពសៀវភៅ \((1, 48), (2, 48.4), (3, 49.5), (4, 48.9), (5, 49.3), (6, 48.7)\) ដើម្បីរកបន្ទាត់តម្រែតម្រង់ពិតប្រាកដ និងប៉ាន់ស្មាននៅឆ្នាំទី ៨ (\(x = 8\)) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក្រុមទី ១ ៖ \(G_1\left(2, \frac{145.9}{3}\right)\) និងក្រុមទី ២ ៖ \(G_2\left(5, \frac{146.9}{3}\right)\) (1 ពិន្ទុ)
មេគុណប្រាប់ទិស ៖ \(a = \frac{146.9/3 - 145.9/3}{5 - 2} = \frac{1}{9}\) (1 ពិន្ទុ)
អរដោនេដើម ៖ \(b = \frac{145.9}{3} - \frac{2}{9} = \frac{4\,357}{90}\) (1 ពិន្ទុ)
ជំនួស \(x = 8\) ៖ \(y(8) = \frac{8}{9} + \frac{4\,357}{90}\) (1 ពិន្ទុ)
ដូច្នេះ \(y(8) = 49.3\) ម៉ឺនក្បាល (ចម្លើយ៖ 49.3) ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'hard', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Evaluate');
