INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22346, 'សម្ពាធបរិយាកាស (\(\text{cm}\) បារត) ថយចុះតាមកម្ពស់ (\(\text{km}\))៖ \((0, 76), (1, 67), (2, 59), (4, 46), (6, 35), (10, 20)\) ។ រកសមីការបន្ទាត់តម្រែតម្រង់កាត់តាមចំណុចមធ្យមពីរ រួចប៉ាន់ស្មានកម្ពស់ពេលសម្ពាធស្មើ \(40\text{ cm}\) ។', 'g12sc-bf78fd85ed.svg', '[]', 0, NULL, 5, 'writing', 'រក \(M_1\left(\frac{0+1+2}{3}, \frac{76+67+59}{3}\right) = \left(1, \frac{202}{3}\right)\) (1 ពិន្ទុ)
រក \(M_2\left(\frac{4+6+10}{3}, \frac{46+35+20}{3}\right) = \left(\frac{20}{3}, \frac{101}{3}\right)\) (1 ពិន្ទុ)
គណនា \(a = \frac{101/3 - 202/3}{20/3 - 1} = -\frac{101}{17}\) និង \(b = \frac{202}{3} + \frac{101}{17} = \frac{3\,737}{51}\) (1 ពិន្ទុ)
សមីការបន្ទាត់ ៖ \(y = -\frac{101}{17}x + \frac{3\,737}{51}\) (1 ពិន្ទុ)
ជំនួស \(y = 40\) ៖ \(x = \frac{1\,697}{303} \approx 5.60\text{ km}\) ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Evaluate');
