INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22347, 'ចំណាយសាងសង់ (ពាន់ដុល្លារ) ក្នុង ៦ ខែ (\(x=0\) តាងមេសា ដល់ \(x=5\) តាងកញ្ញា) គឺ \((0, 24), (1, 19), (2, 30), (3, 49), (4, 68), (5, 67)\) ។ រកបន្ទាត់តម្រែតម្រង់ រួចប៉ាន់ស្មានចំណាយក្នុងខែតុលា (\(x = 6\)) ។', 'g12sc-94867d1da6.svg', '[]', 0, NULL, 5, 'writing', 'រក \(M_1\left(\frac{0+1+2}{3}, \frac{24+19+30}{3}\right) = \left(1, \frac{73}{3}\right)\) (1 ពិន្ទុ)
រក \(M_2\left(\frac{3+4+5}{3}, \frac{49+68+67}{3}\right) = \left(4, \frac{184}{3}\right)\) (1 ពិន្ទុ)
គណនា \(a = \frac{184/3 - 73/3}{4 - 1} = \frac{37}{3}\) និង \(b = \frac{73}{3} - \frac{37}{3} = 12\) (1 ពិន្ទុ)
សមីការបន្ទាត់ ៖ \(y = \frac{37}{3}x + 12\) (1 ពិន្ទុ)
ខែតុលា (\(x = 6\)) ៖ \(y(6) = \frac{37}{3}(6) + 12 = 86\) ពាន់ដុល្លារ ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Evaluate');
