INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22348, 'អត្រាប្រាក់ឈ្នួលកម្មករ (ដុល្លារ/ម៉ោង) តាមឆ្នាំគឺ \((1\,950, 1.5), (1\,952, 1.8), (1\,954, 1.9), (1\,956, 2.5), (1\,958, 2.8), (1\,960, 3.2), (1\,962, 3.7), (1\,964, 4.3)\) ។ រកសមីការបន្ទាត់តម្រែតម្រង់តាមវិធីចំណុចមធ្យមពីរ (ទម្រង់ប្រភាគពិតប្រាកដ) និងប៉ាន់ស្មាននៅឆ្នាំ ១៩៦៦ ។', 'g12sc-22ffc4cb51.svg', '[]', 0, NULL, 5, 'writing', 'រក \(M_1(1\,953, 1.925)\) នៃ ៤ ឆ្នាំដំបូង (១៩៥០–១៩៥៦) (1 ពិន្ទុ)
រក \(M_2(1\,961, 3.5)\) នៃ ៤ ឆ្នាំចុងក្រោយ (១៩៥៨–១៩៦៤) (1 ពិន្ទុ)
គណនា \(a = \frac{3.5 - 1.925}{1\,961 - 1\,953} = \frac{63}{320} \approx 0.197\) (1 ពិន្ទុ)
សមីការបន្ទាត់ ៖ \(y = \frac{63}{320}x - \frac{122\,423}{320}\) (1 ពិន្ទុ)
ឆ្នាំ ១៩៦៦ ៖ \(y(1\,966) = \frac{1\,435}{320} \approx 4.484\) ដុល្លារ/ម៉ោង ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
