INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22349, 'ប្រាក់ចំណូលថ្ងៃចន្ទ \((x)\) និងថ្ងៃសៅរ៍ \((y)\) ក្នុង ៨ សប្តាហ៍គឺ \((43, 72), (65, 83), (56, 79), (63, 84), (56, 80), (56, 76), (56, 74), (51, 79)\) ។ រកបន្ទាត់កាត់តាមចំណុចមធ្យម \(M\) និង \((63, 84)\) រួចប៉ាន់ស្មាន \(y\) ពេល \(x = 70\) ។', 'g12sc-b842b15a2c.svg', '[]', 0, NULL, 5, 'writing', 'គណនា \(\overline{x} = \frac{446}{8} = 55.75\) និង \(\overline{y} = \frac{627}{8} = 78.375\) (1 ពិន្ទុ)
គណនាមេគុណប្រាប់ទិស ៖ \(a = \frac{84 - 78.375}{63 - 55.75} = \frac{45}{58}\) (1 ពិន្ទុ)
គណនាអរដោនេដើម ៖ \(b = 84 - \frac{45}{58}(63) = \frac{2\,037}{58}\) (1 ពិន្ទុ)
សមីការបន្ទាត់ ៖ \(y = \frac{45}{58}x + \frac{2\,037}{58}\) (1 ពិន្ទុ)
ពេល \(x = 70\) បាន \(y = \frac{5\,187}{58} \approx 89.43\) ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
