INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22350, 'ទិន្នន័យការលក់គឺ \((1, 10), (2, 15), (3, 20), (4, 16), (5.5, 30), (6, 25), (7, 35), (9, 40)\) ។ រកសមីការបន្ទាត់តម្រែតម្រង់កាត់តាមចំណុចមធ្យមពីរ ។', 'g12sc-6e7c715f5b.svg', '[]', 0, NULL, 5, 'writing', 'រក \(M_1\) នៃ ៤ ចំណុចដំបូង ៖ \(M_1(2.5, 15.25)\) (1 ពិន្ទុ)
រក \(M_2\) នៃ ៤ ចំណុចចុងក្រោយ ៖ \(M_2(6.875, 32.5)\) (1 ពិន្ទុ)
គណនា \(a = \frac{32.5 - 15.25}{6.875 - 2.5} = \frac{17.25}{4.375} = \frac{138}{35}\) (1 ពិន្ទុ)
គណនា \(b = 15.25 - \frac{138}{35}(2.5) = \frac{151}{28}\) (1 ពិន្ទុ)
ដូច្នេះ \(y = \frac{138}{35}x + \frac{151}{28} \approx 3.943x + 5.393\) ។ (1 ពិន្ទុ)', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 0, '12SC', 'ស្ថិតិមានពីរអថេរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Create');
